# Design tokens - the single source of truth for colour and type.
#
# Two palettes (light, dark) share one set of token names. bslib reads
# app_theme(), the browser reads the --app-* custom properties generated by
# css_root_vars() (light on :root, dark under [data-bs-theme="dark"]), every
# plotly chart reads app_palette(mode) through app_plotly_base(mode), and the
# PDF report receives the light palette in its payload. Change a value here
# and the whole app (and the report) follows. Never hardcode hex elsewhere.
#
# Roles, not colours: `increase` is "costs more", `decrease` is "costs less",
# `warning` is schedule compression / infeasibility. `*_text` variants reach
# 4.5:1 on both surfaces; the bare role colours are for fills and marks (3:1).
# `cat` is the Okabe-Ito categorical set, used only where items are categories
# (languages, complexity levels), never for status.

app_palettes <- list(
  light = list(
    bg            = "#F2F4F6",  # canvas
    surface       = "#FFFFFF",  # cards, sidebar, header
    surface_2     = "#E9EDF1",  # insets, table stripes
    border        = "#D6DCE2",  # hairlines
    ink           = "#15202B",  # body text
    ink_muted     = "#566270",  # secondary text (6.2:1 on white)
    primary       = "#0F4C5C",  # petrol ink: identity, hero figure, highlight series
    primary_dark  = "#0A3542",
    primary_soft  = "#D7E8EC",  # tints, range band
    on_primary    = "#FFFFFF",  # text on a primary fill
    increase      = "#B4500A",  # cost up (fills, marks)
    increase_text = "#8F3F07",
    decrease      = "#1F8A4C",  # cost down (fills, marks)
    decrease_text = "#1B6B3C",
    warning       = "#D97706",  # compression / infeasible (fills, marks)
    warning_text  = "#8A5A00",
    context       = "#A1A8B0",  # grey context bars and lines
    grid          = "rgba(21, 32, 43, 0.08)",
    zero          = "rgba(21, 32, 43, 0.25)",
    cat           = c("#0072B2", "#B26F00", "#008060", "#B4508A", "#2F8FC6", "#D55E00")
  ),
  dark = list(
    bg            = "#0F161C",
    surface       = "#171F27",
    surface_2     = "#1F2932",
    border        = "#2B3641",
    ink           = "#E7ECF0",
    ink_muted     = "#A3AEB9",
    primary       = "#6CC1D3",
    primary_dark  = "#4FA7BA",
    primary_soft  = "#163A44",
    on_primary    = "#0F161C",
    increase      = "#F0956A",
    increase_text = "#F0956A",
    decrease      = "#5FC9A0",
    decrease_text = "#5FC9A0",
    warning       = "#E0B35A",
    warning_text  = "#E0B35A",
    context       = "#6B7681",
    grid          = "rgba(231, 236, 240, 0.10)",
    zero          = "rgba(231, 236, 240, 0.30)",
    cat           = c("#56B4E9", "#E0B35A", "#5FC9A0", "#E29CC4", "#8FC4E8", "#F0956A")
  )
)

#' Palette for a theme mode ("light" or "dark"); anything else falls back to light
app_palette <- function(mode = "light") {
  if (identical(mode, "dark")) app_palettes$dark else app_palettes$light
}

# Light palette alias: the PDF report and ggplot helpers read this name.
app_colors <- app_palettes$light

# Sequential ramp (light) for the few places that need an ordered single-hue scale
app_colors$seq <- c("#D7E8EC", "#A9CBD3", "#7AAEBA", "#4C8FA0", "#0F4C5C", "#0A3542")

#' n-colour sequential palette drawn from the brand ramp
app_seq_palette <- function(n) {
  if (n <= 0) return(character(0))
  grDevices::colorRampPalette(app_colors$seq)(max(n, 2))[seq_len(max(n, 1))]
}

# Type: two families from the same designer, self-hosted from www/fonts
# (declared in www/fonts.css). Serif carries the hero figure and headings;
# sans carries everything else. Both have tabular digits by default.
app_fonts <- list(
  sans  = "'Source Sans 3', 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif",
  serif = "'Source Serif 4', Georgia, 'Times New Roman', serif"
)

#' bslib theme built from the light tokens; dark mode is handled by the
#' --app-* variables flipping under [data-bs-theme="dark"] (see custom.css).
app_theme <- function() {
  p <- app_palettes$light
  bslib::bs_theme(
    version      = 5,
    preset       = "shiny",
    bg           = p$bg,
    fg           = p$ink,
    primary      = p$primary,
    secondary    = p$ink_muted,
    success      = p$decrease,
    warning      = p$warning,
    danger       = p$increase,
    base_font    = "Source Sans 3",
    heading_font = "Source Serif 4",
    code_font    = "ui-monospace, SFMono-Regular, Menlo, monospace",
    "border-radius"    = "6px",
    "border-radius-sm" = "4px",
    "border-radius-lg" = "8px",
    "font-size-base"   = "1rem",
    "headings-font-weight" = "600"
  ) |>
    bslib::bs_add_variables(
      "card-border-color"  = p$border,
      "card-cap-bg"        = p$surface,
      "card-bg"            = p$surface,
      "navbar-light-bg"    = p$surface,
      "input-border-color" = p$border,
      "focus-ring-color"   = "rgba(15, 76, 92, 0.35)"
    )
}

#' Generate the CSS custom-property blocks for both modes.
#' Light values live on :root; dark values re-point the same names under
#' [data-bs-theme="dark"], which bslib::input_dark_mode() toggles per session.
css_root_vars <- function() {
  block <- function(pal, selector) {
    scalar <- pal[!vapply(pal, function(x) length(x) > 1, logical(1))]
    vars <- paste0("  --app-", gsub("_", "-", names(scalar)), ": ",
                   unlist(scalar), ";", collapse = "\n")
    cats <- paste0("  --app-cat-", seq_along(pal$cat), ": ", pal$cat, ";",
                   collapse = "\n")
    paste0(selector, " {\n", vars, "\n", cats, "\n",
           "  --app-font-sans: ", app_fonts$sans, ";\n",
           "  --app-font-serif: ", app_fonts$serif, ";\n}")
  }
  paste(
    block(app_palettes$light, ":root"),
    block(app_palettes$dark,  '[data-bs-theme="dark"]'),
    sep = "\n"
  )
}

#' Shared plotly layout for a theme mode. Pass the session's mode so one
#' user's toggle never restyles another user's charts.
app_plotly_base <- function(mode = "light") {
  p <- app_palette(mode)
  axis <- list(
    color         = p$ink_muted,
    gridcolor     = p$grid,
    zerolinecolor = p$zero,
    linecolor     = p$border,
    tickfont      = list(color = p$ink_muted, size = 12),
    titlefont     = list(color = p$ink_muted, size = 12)
  )
  list(
    paper_bgcolor = "transparent",
    plot_bgcolor  = "transparent",
    font          = list(color = p$ink, family = app_fonts$sans, size = 13),
    hoverlabel    = list(bgcolor = p$surface, bordercolor = p$border,
                         font = list(color = p$ink, family = app_fonts$sans)),
    legend        = list(font = list(color = p$ink), bgcolor = "transparent"),
    xaxis         = axis,
    yaxis         = axis,
    margin        = list(t = 16, r = 16, b = 48, l = 64)
  )
}

# Light alias kept for code that indexes the layout as a list
app_plotly_layout <- app_plotly_base("light")

#' Quiet plotly chrome: no mode bar, no logo, responsive sizing
app_chart_config <- function(p) {
  plotly::config(p, displayModeBar = FALSE, displaylogo = FALSE, responsive = TRUE)
}
